<?php
// میزِ کارِ من: فروش و پورسانت، حسابِ نقدی، حضورِ امروز، مرخصی، فیش‌ها — روالِ Weby staff/my, my-sales, payslips, leave
$m = my_desk();
echo '<div class="stats">' . ui_stat('فروشِ امروزِ من (' . fa_num((string)$m['today_n']) . ')', $m['today']) . ui_stat('فروشِ این ماه', $m['month']) . ui_stat('پورسانتِ این ماه', $m['commission']) . ui_stat('حسابِ نقدیِ من (بدهی)', $m['cash']) . ($m['emp'] ? '<div class="stat"><span>ماندهٔ مرخصی</span><b>' . fa_num(rtrim(rtrim(number_format($m['leave_bal'], 1, '.', ''), '0'), '.')) . ' روز</b></div>' : '') . '</div>';
echo '<div class="cols">';
if ($m['emp']) echo ui_card('حضورِ امروز', '<p>ورود: <b>' . h(fa_num((string)($m['att']['t_in'] ?? '—'))) . '</b> · خروج: <b>' . h(fa_num((string)($m['att']['t_out'] ?? '—'))) . '</b>' . (!empty($m['att']['late_min']) ? ' · تأخیر ' . fa_num((string)$m['att']['late_min']) . ' دقیقه' : '') . '</p><p class="muted">برای کارت‌زدن، QRِ ایستگاهِ محلِ کار را با همین گوشی اسکن کنید.</p>')
    . ui_card('مرخصی', ui_form('leave_self', ['kind' => ['نوع', 'select', 1, leave_kinds()], 'from' => ['از', 'date', 1], 'to' => ['تا', 'date'], 'days' => ['روز (ساعتی: ۰٫۵)', 'float'], 'note' => ['توضیح', 'text']], [], ['submit' => 'درخواست'])
    . ui_table(['from_d' => ['از', 'date'], 'to_d' => ['تا', 'date'], 'days' => ['روز', 'num'], 'kind' => ['نوع', fn($r) => leave_kinds()[$r['kind']] ?? ''], 'status' => ['وضعیت', fn($r) => ui_badge(['pending' => 'در انتظار', 'approved' => 'تأیید', 'rejected' => 'رد'][$r['status']] ?? $r['status'], ['approved' => 'ok', 'rejected' => 'err', 'pending' => 'warn'][$r['status']] ?? '') . ($r['decision_note'] ? ' <small>' . h($r['decision_note']) . '</small>' : '')]], $m['leaves'], ['empty' => '—']));
else echo ui_card('پروندهٔ پرسنلی', '<p class="muted">حسابِ شما به پروندهٔ پرسنلی وصل نیست؛ حضور، مرخصی و فیش از منابعِ انسانی وصل می‌شود.</p>');
echo ui_card('فروش‌های اخیرِ من', ui_table(['number' => ['شماره', 'num'], 'at' => ['زمان', 'datetime'], 'total' => ['مبلغ', 'money']], $m['sales'], ['href' => can('docs.view') ? fn($r) => page_url('sale', ['id' => $r['id']]) : null, 'empty' => '—']));
if ($m['payslips']) echo ui_card('فیش‌های حقوقیِ من', ui_table(['ym' => ['ماه', fn($r) => fa_num(str_replace('-', '/', $r['ym']))], 'gross' => ['ناخالص', 'money'], 'net' => ['خالص', 'money'], 'status' => ['وضعیت', fn($r) => $r['status'] === 'paid' ? ui_badge('پرداخت‌شده', 'ok') : 'قطعی'], 'a' => ['', fn($r) => '<a class="btn sm" target="_blank" href="index.php?p=print_payslip&id=' . $r['id'] . '&mine=1">فیش</a>']], $m['payslips']));
echo '</div>';
